import{_ as e,c as r,o as t,ae as i}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"隐私与数据","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy.md","filePath":"zh-CN/guide/privacy.md","lastUpdated":1795170900000}'),o={name:"zh-CN/guide/privacy.md"};function l(n,a,h,c,s,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="隐私与数据" tabindex="-1">隐私与数据 <a class="header-anchor" href="#隐私与数据" aria-label="Permalink to &quot;隐私与数据&quot;">​</a></h1><p>哪些内容留在你的 Mac 上，哪些情况需要联网。</p><h2 id="保存在本机" tabindex="-1">保存在本机 <a class="header-anchor" href="#保存在本机" aria-label="Permalink to &quot;保存在本机&quot;">​</a></h2><p>历史、书签、当前标签、下载记录和 Cookie 都保存在本地。没有账户，也没有云同步。无痕窗口（⌘⇧N）不会写入历史与会话。</p><h2 id="什么时候会联网" tabindex="-1">什么时候会联网 <a class="header-anchor" href="#什么时候会联网" aria-label="Permalink to &quot;什么时候会联网&quot;">​</a></h2><ul><li>打开你访问的网站，这是理所当然的。</li><li>启用了广告订阅时，更新订阅规则。更新失败也会沿用已保存的规则。</li><li>下载你主动请求的用户脚本或文件。</li></ul><h2 id="权限由你决定" tabindex="-1">权限由你决定 <a class="header-anchor" href="#权限由你决定" aria-label="Permalink to &quot;权限由你决定&quot;">​</a></h2><p>摄像头和麦克风按网站记住：你可以允许一个站点、拒绝另一个。定位与通知由 macOS 系统管理。弹窗默认只放行你允许的站点。</p><h2 id="磁盘上的文件" tabindex="-1">磁盘上的文件 <a class="header-anchor" href="#磁盘上的文件" aria-label="Permalink to &quot;磁盘上的文件&quot;">​</a></h2><p>Persim 只会读取你在系统文件面板里选择、或明确授权过的文件夹，授权情况可以在设置中查看和撤销。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>关于隐私的问题：<strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',12)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
